import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:intl/intl.dart';
import 'package:uuid/uuid.dart';
import 'package:url_launcher/url_launcher.dart';
import 'models/records.dart';
import 'storage/ledger_store.dart';
import 'theme/app_theme.dart';
import 'screens/kiosk_screen.dart';
import 'screens/tanks_screen.dart';
import 'screens/faults_screen.dart';
import 'screens/settings_screen.dart';

Future<void> main() async { WidgetsFlutterBinding.ensureInitialized(); await LedgerStore.instance.init(); runApp(const MajiTraceApp()); }
class MajiTraceApp extends StatefulWidget { const MajiTraceApp({super.key}); @override State<MajiTraceApp> createState()=>_MajiTraceAppState(); }
class _MajiTraceAppState extends State<MajiTraceApp> {
 final store=LedgerStore.instance; int tab=0; late String role,theme; late double tariff,capacity,baseline; List<WaterSale> sales=[]; List<Refill> refills=[]; List<FaultTicket> faults=[];
 bool get admin=>role=='Water Committee Admin';
 @override void initState(){super.initState();_reload();}
 void _reload(){role=store.role;theme=store.theme;tariff=store.tariff;capacity=store.tankCapacity;baseline=store.tankBaseline;sales=store.sales;refills=store.refills;faults=store.faults;}
 double get tankLevel=>(baseline+refills.fold<double>(0,(s,e)=>s+e.liters)-sales.fold<double>(0,(s,e)=>s+e.quantity)).clamp(0,capacity);
 Future<void> _refresh()async{setState(_reload);}
 Future<void> _sale()async{final f=await _dialog('Record dispensing', [('Customer / account','Walk-in'),('Quantity in litres','20'),('Amount paid (KES)','0'),('Payment mode','Cash')]);if(f==null)return;final q=double.tryParse(f[1])??0,p=double.tryParse(f[2])??0;if(q<=0||p<0)return;final v=[...sales,WaterSale(id:const Uuid().v4(),customer:f[0],quantity:q,unit:'L',unitPrice:tariff,paid:p.clamp(0,q*tariff),paymentMode:f[3],createdAt:DateTime.now())];await store.saveSales(v);await _refresh();}
 Future<void> _refill()async{final f=await _dialog('Record tank refill',[('Source / supplier','Borehole'),('Litres added','1000'),('Cost (KES)','0'),('Notes','')]);if(f==null)return;final l=double.tryParse(f[1])??0,c=double.tryParse(f[2])??0;if(l<=0)return;await store.saveRefills([...refills,Refill(id:const Uuid().v4(),source:f[0],liters:l,cost:c,createdAt:DateTime.now(),note:f[3])]);await _refresh();}
 Future<void> _fault()async{final f=await _dialog('Report fault',[('Location','Kiosk tap'),('Issue','Leaking tap'),('Severity (Urgent/Routine)','Routine'),('Details','')]);if(f==null)return;await store.saveFaults([...faults,FaultTicket(id:const Uuid().v4(),location:f[0],issue:f[1],severity:f[2].toLowerCase().contains('urgent')?'Urgent':'Routine',status:'Open',createdAt:DateTime.now(),notes:f[3])]);await _refresh();}
 Future<List<String>?> _dialog(String title,List<(String,String)> fields)async{final ctrls=fields.map((e)=>TextEditingController(text:e.$2)).toList();return showDialog<List<String>>(context:context,builder:(ctx)=>AlertDialog(title:Text(title),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:List.generate(fields.length,(i)=>Padding(padding:const EdgeInsets.only(bottom:10),child:TextField(controller:ctrls[i],decoration:InputDecoration(labelText:fields[i].$1))))),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,ctrls.map((c)=>c.text.trim()).toList()),child:const Text('Save'))]));}
 Future<void> _downloadApk() async { final uri=Uri.parse('https://github.com/kennedy-blip/maji-trace/releases/latest/download/app-release.apk'); final ok=await launchUrl(uri,mode:LaunchMode.externalApplication); if(!ok&&mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('APK release is not available yet. Check the GitHub Actions build.'))); }
 Future<void> _tankConfig((double,double) v) async { await store.setTank(capacity:v.$2,baseline:v.$1); await _refresh(); }
 Future<void> _export()async{final lines=['MAJITRACE LEDGER • ${DateFormat.yMMMd().format(DateTime.now())}','DISPENSING','Customer,Quantity,Unit price,Total,Paid,Balance,Payment'];for(final s in sales){lines.add('${s.customer},${s.quantity},${s.unitPrice},${s.total},${s.paid},${s.balance},${s.paymentMode}');}lines.add('REFILLS');for(final r in refills){lines.add('${r.source},${r.liters},${r.cost},${r.createdAt.toIso8601String()}');}lines.add('FAULTS');for(final f in faults){lines.add('${f.location},${f.issue},${f.severity},${f.status}');}await Clipboard.setData(ClipboardData(text:lines.join('\n')));if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Ledger CSV copied to clipboard')));}
 @override Widget build(BuildContext context)=>MaterialApp(debugShowCheckedModeBanner:false,title:'MajiTrace',theme:buildTheme(theme),home:Scaffold(body:Container(decoration:BoxDecoration(gradient:LinearGradient(begin:Alignment.topLeft,end:Alignment.bottomRight,colors:theme=='Daylight Spring'?[const Color(0xffd9f4ed),const Color(0xfff5fbfa)]:[const Color(0xff07131f),const Color(0xff102b3b),const Color(0xff07131f)])),child:SafeArea(child:Column(children:[_header(),Expanded(child:AnimatedSwitcher(duration:const Duration(milliseconds:280),child:KeyedSubtree(key:ValueKey(tab),child:_screen())))]))),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:const [NavigationDestination(icon:Icon(Icons.water_drop_outlined),label:'Kiosk'),NavigationDestination(icon:Icon(Icons.opacity),label:'Tanks'),NavigationDestination(icon:Icon(Icons.build_outlined),label:'Faults'),NavigationDestination(icon:Icon(Icons.settings_outlined),label:'Settings') ])));
 Widget _header()=>Padding(padding:const EdgeInsets.fromLTRB(18,12,18,8),child:Row(children:[Container(width:42,height:42,decoration:BoxDecoration(color:aqua.withValues(alpha:.16),borderRadius:BorderRadius.circular(14)),child:const Icon(Icons.water_drop,color:aqua)),const SizedBox(width:10),const Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('MajiTrace',style:TextStyle(fontSize:20,fontWeight:FontWeight.w900)),Text('WATER OPERATIONS LEDGER',style:TextStyle(fontSize:9,letterSpacing:1.5))])),PopupMenuButton<String>(tooltip:'Switch role',onSelected:(v)async{await store.setRole(v);setState(()=>role=v);},itemBuilder:(_)=>const [PopupMenuItem(value:'Water Committee Admin',child:Text('Committee Admin')),PopupMenuItem(value:'Kiosk Attendant',child:Text('Kiosk Attendant'))],child:Chip(avatar:Icon(admin?Icons.admin_panel_settings:Icons.badge,size:17),label:Text(admin?'Admin':'Staff')))]));
 Widget _screen()=>switch(tab){0=>KioskScreen(sales:sales,onAdd:_sale,onDelete:(s)async{if(admin){await store.saveSales(sales.where((e)=>e.id!=s.id).toList());await _refresh();}},admin:admin),1=>TanksScreen(refills:refills,level:tankLevel,capacity:capacity,onAdd:_refill),2=>FaultsScreen(faults:faults,onAdd:_fault,admin:admin,onResolve:(f)async{await store.saveFaults(faults.map((e)=>e.id==f.id?FaultTicket(id:e.id,location:e.location,issue:e.issue,severity:e.severity,status:'Resolved',createdAt:e.createdAt,notes:e.notes,repairNotes:'Marked resolved by admin'):e).toList());await _refresh();}),_=>SettingsScreen(role:role,theme:theme,tariff:tariff,records:store.recordCount,capacity:capacity,baseline:baseline,onRole:(v)async{await store.setRole(v);setState(()=>role=v);},onTheme:(v)async{await store.setTheme(v);setState(()=>theme=v);},onTariff:(v)async{await store.setTariff(v);setState(()=>tariff=v);},onTankConfig:_tankConfig,onDownloadApk:_downloadApk,onExport:_export)};
}
